@namespace sv_c126f3be86424d439b8152a6ea56534e.Components.Pages.Settings

<nav class="settings-sidebar">
    <h2 class="sidebar-title">Settings</h2>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_c126f3be86424d439b8152a6ea56534e.Services
@namespace sv_c126f3be86424d439b8152a6ea56534e.Components.Pages.Settings

<div class="settings-section profile-section">
    <h3>Profile Settings</h3>

    @if (_successMessage is not null)
    {
        <div class="toast success">@_successMessage</div>
    }

    <div class="profile-form">
        <div class="avatar-preview">
            <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
            <p class="avatar-url">@_avatarUrl</p>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" class="form-control" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" class="form-control" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio" class="form-control" rows="4"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private string? _successMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && _displayName == "")
        {
            LoadFromProfile(Profile);
        }
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
        _successMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

@using sv_c126f3be86424d439b8152a6ea56534e.Services
@namespace sv_c126f3be86424d439b8152a6ea56534e.Components.Pages.Settings

<div class="settings-section notifications-section">
    <h3>Notification Preferences</h3>

    <div class="toggle-group">
        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="_emailNotifications" class="toggle-input" />
                <span class="toggle-switch"></span>
                Email Notifications
            </label>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="_pushNotifications" class="toggle-input" />
                <span class="toggle-switch"></span>
                Push Notifications
            </label>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="_weeklyDigest" class="toggle-input" />
                <span class="toggle-switch"></span>
                Weekly Digest
            </label>
        </div>
    </div>

    <div class="muted-channels">
        <h4>Muted Channels</h4>
        @foreach (var channel in _availableChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@_mutedChannels.Contains(channel)"
                       @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                @channel
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = new();
    private readonly List<string> _availableChannels = new() { "general", "marketing", "announcements", "engineering", "random" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new List<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!isMuted)
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
        await OnSave.InvokeAsync(updated);
    }
}

@using sv_c126f3be86424d439b8152a6ea56534e.Services
@namespace sv_c126f3be86424d439b8152a6ea56534e.Components.Pages.Settings

<div class="settings-section security-section">
    <h3>Security Settings</h3>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span>Change Password</span>
            <span class="panel-toggle">@(_passwordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (_passwordPanelOpen)
        {
            <div class="panel-content">
                @if (_passwordError is not null)
                {
                    <div class="toast error">@_passwordError</div>
                }
                @if (_passwordSuccess is not null)
                {
                    <div class="toast success">@_passwordSuccess</div>
                }

                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
                </div>
                <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <div class="tfa-row">
            <div class="tfa-info">
                <span class="tfa-label">Two-Factor Authentication</span>
                <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <label class="toggle-label">
                <input type="checkbox" @bind="_twoFactorEnabled" class="toggle-input" />
                <span class="toggle-switch"></span>
            </label>
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h4>Active Sessions</h4>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @if (Security?.Sessions is not null)
                {
                    @foreach (var session in Security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != _currentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="dialog-overlay" @onclick="CancelRevoke">
            <div class="dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ExecuteRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private string? _passwordSuccess;
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private readonly string _currentSessionId = "session-1";

    protected override void OnParametersSet()
    {
        if (Security is not null)
        {
            _twoFactorEnabled = Security.TwoFactorEnabled;
        }
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _passwordSuccess = "Password updated successfully!";
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ExecuteRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@using sv_c126f3be86424d439b8152a6ea56534e.Services
@namespace sv_c126f3be86424d439b8152a6ea56534e.Components.Pages.Settings

<div class="settings-section appearance-section">
    <h3>Appearance Settings</h3>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in _themes)
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    @theme
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in _fontSizes)
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    @size
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="_language" class="form-control">
            @foreach (var lang in _languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <div class="toggle-item">
        <label class="toggle-label">
            <input type="checkbox" @bind="_compactMode" class="toggle-input" />
            <span class="toggle-switch"></span>
            Compact Mode
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <div class="preview-content">
            <p class="preview-text">This is how your content will look with the selected settings.</p>
            <button class="preview-button">Sample Button</button>
            <div class="preview-card">
                <span class="preview-card-title">Card Title</span>
                <span class="preview-card-body">Card content goes here.</span>
            </div>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly string[] _themes = { "Light", "Dark", "System" };
    private readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
    }
}

