.tfa-section {
    margin-bottom: 1.5rem;
    padding: 1rem 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
}

.tfa-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.tfa-info {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.tfa-label {
    font-weight: 500;
}

.status-indicator {
    font-size: 0.8rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-weight: 500;
}

.status-enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-disabled {
    background: #fff3e0;
    color: #e65100;
}

/* Sessions Table */
.sessions-section {
    margin-top: 1.5rem;
