+.settings-dashboard {
+    display: flex;
+    min-height: calc(100vh - 4rem);
+    gap: 0;
+}
+
+/* Sidebar */
+.settings-sidebar {
+    width: 240px;
+    background: #f8f9fa;
+    border-right: 1px solid #e0e0e0;
+    padding: 1.5rem 0;
+    flex-shrink: 0;
+}
+
+.sidebar-title {
+    padding: 0 1.5rem;
