+.tfa-section {
+    margin-bottom: 1.5rem;
+    padding: 1rem 1.25rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+}
+
+.tfa-row {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+}
+
+.tfa-info {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+}
+
+.tfa-label {
+    font-weight: 500;
+}
+
+.status-indicator {
+    font-size: 0.8rem;
+    padding: 0.2rem 0.6rem;
+    border-radius: 12px;
+    font-weight: 500;
+}
+
+.status-enabled {
+    background: #e8f5e9;
+    color: #2e7d32;
+}
+
+.status-disabled {
+    background: #fff3e0;
+    color: #e65100;
+}
+
+/* Sessions Table */
+.sessions-section {
+    margin-top: 1.5rem;
+}
+
+.sessions-section h4 {
+    margin: 0 0 0.75rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    color: #555;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    padding: 0.2rem 0.5rem;
+    background: #e3f2fd;
+    color: #1565c0;
+    border-radius: 4px;
+    font-weight: 500;
+}
+
+/* Dialog */
+.dialog-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: white;
+    padding: 1.5rem;
+    border-radius: 12px;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
+}
+
+.dialog h4 {
+    margin: 0 0 0.75rem;
+}
+
+.dialog p {
+    margin: 0 0 1.25rem;
+    color: #555;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.4rem;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Appearance Preview */
+.preview-area {
+    margin: 1.5rem 0;
+    padding: 1.5rem;
