+    letter-spacing: 0.05em;
+    color: #777;
+}
+
+.preview-content {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+}
+
+.preview-text {
+    margin: 0;
+}
+
+.preview-button {
+    align-self: flex-start;
+    padding: 0.5rem 1rem;
+    border: none;
+    border-radius: 6px;
+    cursor: pointer;
+    background: #1565c0;
+    color: white;
+}
+
+.preview-card {
+    padding: 1rem;
+    border: 1px solid #ddd;
+    border-radius: 6px;
+    display: flex;
+    flex-direction: column;
+    gap: 0.4rem;
+}
+
+.preview-card-title {
+    font-weight: 600;
+}
+
+.preview-card-body {
+    color: #666;
+    font-size: 0.9em;
+}
+
+/* Theme variants */
+.preview-theme-dark {
+    background: #1a1a2e;
+    color: #e0e0e0;
+    border-color: #333;
+}
+
+.preview-theme-dark .preview-card {
+    border-color: #444;
+    background: #16213e;
+}
+
+.preview-theme-dark .preview-card-body {
+    color: #aaa;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-theme-system {
+    background: #f5f5f5;
+    color: #333;
+}
+
+/* Font size variants */
+.preview-font-small {
+    font-size: 0.85rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.15rem;
+}
+
+/* Compact mode */
+.preview-compact {
+    padding: 0.75rem;
+}
+
+.preview-compact .preview-content {
+    gap: 0.4rem;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+}
+
